 static string CommandTitle(string code){var line=code.Replace("\r","").Split('\n').FirstOrDefault(t=>!string.IsNullOrWhiteSpace(t))?.Trim()??"Команда";return line.Length>70?line[..67]+"…":line;}
 static string EntryKey(LibraryEntry entry)=>entry.MicrosoftSource+"|"+string.Join("\u001f",entry.Steps.Select(t=>t.Kind+":"+t.Code.Replace("\r\n","\n").Trim()));
 static bool TextSteps(IEnumerable<CommandStep> steps)=>steps.Any()&&steps.All(t=>t.Kind is "CMD" or "PowerShell");
 IEnumerable<CommandSuggestion> SuggestionCandidates(){var seen=new HashSet<string>(StringComparer.Ordinal);foreach(var entry in Library.Where(e=>TextSteps(e.Steps)).OrderByDescending(e=>e.Favorite)){if(seen.Add(EntryKey(entry)))yield return new(){Entry=entry,Source="Сохранённая"};}foreach(var job in History.Where(j=>!IsWsusJob(j)&&TextSteps(j.Steps))){var entry=new LibraryEntry{Name=job.Name,MicrosoftSource=job.MicrosoftSource,Steps=Store.Clone(job.Steps)};if(seen.Add(EntryKey(entry)))yield return new(){Entry=entry,Source="Ранее введённая"};}}
 void UpdateSuggestions(bool all=false){if(SuggestionList==null)return;SuggestionBorder.Width=Math.Max(180,Math.Min(Editor.ActualWidth,700));string query=all?"":Editor.Text.Trim();Suggestions.Clear();foreach(var item in SuggestionCandidates().Where(x=>query==""||(x.Name+" "+x.Preview).Contains(query,StringComparison.OrdinalIgnoreCase)).Take(30))Suggestions.Add(item);SuggestionsPopup.IsOpen=Suggestions.Count>0;}
 void Editor_Changed(object s,TextChangedEventArgs e){if(DataContext!=null&&!applyingSuggestion&&Editor.IsKeyboardFocusWithin){if(Editor.Text.Trim().Length>0)UpdateSuggestions();else SuggestionsPopup.IsOpen=false;}}
 void ShowSuggestions_Click(object s,RoutedEventArgs e){UpdateSuggestions(true);if(Suggestions.Count==0)Notify("Сохранённых и недавних команд пока нет.");}
 void ApplySuggestion(){if(SuggestionList.SelectedItem is not CommandSuggestion item)return;applyingSuggestion=true;try{var entry=item.Entry;MicrosoftBox.IsChecked=entry.MicrosoftSource;Editor.Text=entry.Steps[0].Code;KindBox.SelectedIndex=entry.Steps[0].Kind=="PowerShell"?1:0;Steps.Clear();if(entry.Steps.Count>1)CommandOptions.IsExpanded=true;if(entry.Steps.Count>1)foreach(var step in Store.Clone(entry.Steps))Steps.Add(step);SuggestionsPopup.IsOpen=false;Editor.Focus();Editor.CaretIndex=Editor.Text.Length;Notify(entry.Steps.Count>1?"Подставлен набор из "+entry.Steps.Count+" шагов. Запуск: «Выполнить набор шагов».":"Команда подставлена. Для запуска нажмите «Выполнить команду».");}finally{applyingSuggestion=false;}}
