 void RestoreCommandLayout(){var layout=Store.Read("command-layout.json",new CommandLayout());double ratio=Math.Clamp(layout.EditorRatio,0.10,0.80);EditorRow.Height=new GridLength(ratio,GridUnitType.Star);ResultRow.Height=new GridLength(1-ratio,GridUnitType.Star);}
