 ComputerRow WithHistory(TargetRecord identity){var job=History.FirstOrDefault(j=>j.Targets.Any(t=>t.Host.Equals(identity.Host,StringComparison.OrdinalIgnoreCase)));var saved=job?.Targets.First(t=>t.Host.Equals(identity.Host,StringComparison.OrdinalIgnoreCase));var target=Store.Clone(identity);target.ConnectionSnapshot=false;var ad=adActivity.FirstOrDefault(t=>t.Host.Equals(identity.Host,StringComparison.OrdinalIgnoreCase)&&(identity.DirectoryId.Length==0||identity.DirectoryId==t.DirectoryId));if(ad!=null&&string.CompareOrdinal(ad.AdCollectedUtc,identity.AdCollectedUtc)>0){target.DirectoryId=ad.DirectoryId;target.AdLastLogonUtc=ad.AdLastLogonUtc;target.AdCollectedUtc=ad.AdCollectedUtc;target.AdDisabled=ad.AdDisabled;}if(saved!=null){target.Status=saved.Status;target.State=Store.Clone(saved.State);target.Output=saved.Output;}return new(target,job?.Id??"");}
 void LoadRows(List<TargetRecord> targets){historyViewId="";loadingRows=true;try{Computers.Clear();foreach(var t in targets.Concat(manualComputers).DistinctBy(t=>t.Host,StringComparer.OrdinalIgnoreCase))Computers.Add(WithHistory(t));Tree();if(Computers.Count>0)ComputerGrid.SelectedItem=Computers.FirstOrDefault(r=>r.Host.Equals(viewState.Host,StringComparison.OrdinalIgnoreCase))??Computers[0];}finally{loadingRows=false;}ShowCurrent();RevealCurrent();RefreshOutcomes();RefreshRecent();RequestOverviewSoon();}
 IEnumerable<ComputerRow> ActivePollRows(){var all=History.SelectMany(j=>j.Targets.Select(t=>(Job:j,Target:t)));var latest=all.GroupBy(x=>x.Target.Host.ToUpperInvariant()+"|"+IsWsusJob(x.Job)).Select(g=>g.First()).Where(x=>x.Target.Status is "AwaitingReboot" or "RebootScheduled");return all.Where(x=>(x.Target.Status is "Sending" or "SubmissionUnknown" or "Submitted" or "Running")||(x.Target.Status=="Queued"&&x.Target.State!=null)||(x.Target.State?.DiagnosticStatus is "Pending" or "Running" or "LegacyRunning")).Concat(latest).DistinctBy(x=>x.Job.Id+"|"+x.Target.Host.ToUpperInvariant()).Select(x=>new ComputerRow(x.Target,x.Job.Id));}

 static bool IsWsusJob(RemoteJob job)=>job.OutputChannel=="WSUS"||(job.OutputChannel==""&&job.Steps.Any(t=>t.Kind is "Updates" or "UpdateScan" or "Diagnostics"));
 RemoteJob? ChannelJob(ComputerRow row,bool wsus){var explicitJob=History.FirstOrDefault(j=>j.Id==historyViewId&&IsWsusJob(j)==wsus&&j.Targets.Any(t=>t.Host.Equals(row.Host,StringComparison.OrdinalIgnoreCase)));return explicitJob??History.FirstOrDefault(j=>IsWsusJob(j)==wsus&&j.Targets.Any(t=>t.Host.Equals(row.Host,StringComparison.OrdinalIgnoreCase)));}
 ComputerRow ExecutionRow(ComputerRow row,bool wsus){var job=ChannelJob(row,wsus);return job==null?new ComputerRow(new TargetRecord{Name=row.Name,Host=row.Host,OS=row.OS,OU=row.OU,Status="Не проверен"}):new ComputerRow(job.Targets.First(t=>t.Host.Equals(row.Host,StringComparison.OrdinalIgnoreCase)),job.Id);}
