 static string CommandOutput(string output,bool wsus)=>LogPresentation.LocalTimes(LogPresentation.Compact(wsus?output:Regex.Replace(output,@"(?m)^Отчёт WSUS:[^\r\n]*(?:\r?\n|$)","")));
 string ChannelOutput(ComputerRow row,bool wsus){var r=ExecutionRow(row,wsus);var stored=r.Target.Output;if(r.Target.State!=null&&!stored.StartsWith("## ")&&stored.Contains("--- runner.log ---")){var legacy=new PollResult{State=r.Target.State,Output=stored};foreach(Match match in Regex.Matches(stored,@"(?ms)^--- [^\r\n]*updates\.json ---\r?\n(.*?)(?=^--- |\z)")){try{legacy.Updates.AddRange(JsonSerializer.Deserialize<List<UpdateOutcome>>(match.Groups[1].Value.Trim(),Store.Options)??new());}catch{}}stored=PresentResult(r.Host,legacy);}var output=!string.IsNullOrWhiteSpace(stored)?CommandOutput(stored,wsus):r.JobId==""?(wsus?"Для этого компьютера пока нет сохранённых заданий WSUS.":"Для этого компьютера пока нет результатов команд."):"Задание: "+r.JobId+"\nСостояние: "+r.Status+"\nОжидание результата…";return CompactJournal31(output+StatusDiagnosticText(row.Host)+(wsus?MaintenanceText(row.Host)+ReportRecoveryText(row.Host):"")+(servicingReports.TryGetValue(r.JobId+row.Host,out var diagnostic)?"\n\n## Технические подробности · первичная диагностика\n"+diagnostic:"")).Trim();}
