 async Task Submit(List<CommandStep> source,string channel="Commands",bool focusOnly=false,bool fullMaintenance=false){SuggestionsPopup.IsOpen=false;if(source.Count==0)throw new Exception("Добавьте команды.");var marked=focusOnly?new List<ComputerRow>():Selected();var focused=ComputerGrid.SelectedItem as ComputerRow;if(focused==null&&marked.Count==0)throw new Exception("Выберите компьютер или отметьте цели.");if(!int.TryParse(LimitBox.Text,out limit)||limit<0)throw new Exception("Лимит: целое число от 0.");if(MicrosoftBox.IsChecked==true&&source.Any(x=>x.Kind is "Updates" or "UpdateScan"))throw new Exception("Разделите восстановление Microsoft и обновления WSUS.");var steps=Store.Clone(source);if(AutoServiceEnabled&&channel=="WSUS"&&steps.Count==1&&steps[0].Code.Contains("function Save-Dependents("))steps.Add(new(){Kind="UpdateScan",Name="Поиск после восстановления служб"});if(!AutoServiceEnabled&&steps.Count>1&&(steps[0].Kind is "CacheCleanup" or "ReportRecovery"))steps=steps.Take(1).ToList();if(!ConfirmShells(steps))return;if(IsIndependentControl(steps)){MicrosoftBox.IsChecked=false;foreach(var step in steps)step.TouchesUpdates=false;}
  foreach(var name in Regex.Matches(string.Join("\n",steps.Select(x=>x.Code)),@"\{\{([A-Za-z][A-Za-z0-9_]*)\}\}").Select(m=>m.Groups[1].Value).Distinct()){var value=Prompt("Параметр "+name);if(value==null)return;foreach(var t in steps)t.Code=t.Code.Replace("{{"+name+"}}",value);}
  var preview=(fullMaintenance?"Полное обслуживание: поиск, скачивание и установка; после вручную разрешённой перезагрузки — продолжение. До 3 циклов, срок 2 суток. Автоматическая перезагрузка не разрешается этим режимом.\n\n":"")+"Источник восстановления Microsoft: "+(MicrosoftBox.IsChecked==true?"временное переключение включено; Kerio этим не разблокируется":"текущие политики клиента")+"\nАвтоперезагрузка: "+(RebootBox.IsChecked==true?"включена":"выключена")+"\n\n"+string.Join("\n\n",steps.Select(t=>t.Name+" ["+t.Kind+"]\n"+(t.Kind=="ReportRecovery"?"Очистка только кэша отчётности. Параметр сохранения копии выбирается галочкой выше. Затем выполняются поиск и запрос отчёта.":t.Code)));var confirmation=new TargetConfirmation(this,focused,marked,preview,steps.Any(t=>t.Kind=="ReportRecovery"));if(confirmation.ShowDialog()!=true)return;var selected=confirmation.Result!;bool exclusive=Maintenance(steps,MicrosoftBox.IsChecked==true);if(!await EnsureEndpointCredentials(selected))return;if(!await PrepareUpdateAction(selected,steps,MicrosoftBox.IsChecked==true))return;bool queueAfter=waitForUpdateConflict;foreach(var step in steps.Where(t=>t.Kind=="ReportRecovery"))step.Code=CacheScripts.Build("Queue",confirmation.KeepReportBackup,false);

  historyViewId="";var job=new RemoteJob{ScanAfterReboot=postReboot.Scan,OutputChannel=channel,IndependentControl=IsIndependentControl(steps),AllowUpdateConflict=forceUpdateConflict,ExclusiveMaintenance=exclusive,QueueAfterWsus=queueAfter,StallMinutes=Store.Read("stall-minutes.json",10),Name=steps[0].Name,Steps=steps,MicrosoftSource=MicrosoftBox.IsChecked==true,AutoReboot=RebootBox.IsChecked==true,ContinueOnError=!steps.Any(t=>t.Kind is "ReportRecovery" or "CacheCleanup"||t.Code.Contains("function Save-Dependents("))&&ContinueBox.IsChecked==true,DiagnosticLookbackMinutes=ReadDiagnosticMinutes()};foreach(var r in selected){var t=ConnectionStore.Capture(r.Target);t.Status="Queued";t.State=null;t.Output="";job.Targets.Add(t);r.JobId=job.Id;confirmedJobs.Add(job.Id+r.Host);queue.Enqueue((job,t));}History.Insert(0,job);if(fullMaintenance||(AutoServiceEnabled&&channel=="WSUS"&&steps.Any(s=>s.Kind is "Updates" or "UpdateScan" or "CacheCleanup" or "ReportRecovery")))BeginMaintenance(job);foreach(var r in selected)RememberComputer(r.Host);if(channel=="WSUS"){foreach(var r in selected){wsusFailureDetails.Remove(r.Host);liveReports.Remove(r.Host);if(reportCache.TryGetValue(r.Host,out var cached)){cached.Started=job.Created;serverReports[r.Host]=CachedReportText(cached);reportSeverity[r.Host]=cached.Report.Severity(job.Created);}}Store.Write("wsus-report-cache.json",reportCache);}Save();Sync(job);if(confirmation.BatchChosen)ClearSelection_Click(this,new RoutedEventArgs());ComputerGrid.SelectedItem=selected[0];MainTabs.SelectedItem=channel=="WSUS"?WsusTab:CommandsTab;ShowCurrent();SuggestionsPopup.IsOpen=false;await SendQueue();
 }
 void Sync(RemoteJob job){job.RefreshSummary();foreach(var row in Computers.Where(r=>r.JobId==job.Id)){var t=job.Targets.FirstOrDefault(t=>t.Host==row.Host);if(t==null)continue;row.Target.Status=t.Status;row.Target.State=t.State;row.Target.Output=t.Output;row.Refresh();}RefreshBranches();RefreshOutcomes();}
 async Task SendQueue(){if(sending||closing)return;sending=true;try{while(queue.Count>0&&!closing){int active=History.SelectMany(j=>j.Targets).Count(t=>t.Status is "Sending" or "Submitted" or "Running");var urgent=queue.FirstOrDefault(q=>q.Job.IndependentControl);if(limit>0&&active>=limit&&urgent.Job==null)break;var next=urgent.Job!=null?urgent:queue.Peek();var pendingQueue=queue.ToList();queue.Clear();bool removed=false;foreach(var q in pendingQueue){if(!removed&&q==next){removed=true;continue;}queue.Enqueue(q);}next.Target.Status="Sending";Sync(next.Job);Save();_=SendOne(next.Job,next.Target);await Task.Delay(80);}}finally{sending=false;}}
 readonly HashSet<string> deploying=new();
 async Task SendOne(RemoteJob job,TargetRecord target){deploying.Add(job.Id+target.Host);try{await remote.Deploy(target,job);confirmedJobs.Add(job.Id+target.Host);target.Status="Submitted";target.Output="Задание передано на "+target.Host+". Ожидание результата…";}catch(Exception ex){target.Status=ex is TimeoutException?"SubmissionUnknown":ex.Message.Contains("Отказано в доступе",StringComparison.OrdinalIgnoreCase)||ex.Message.Contains("Access is denied",StringComparison.OrdinalIgnoreCase)?"AccessDenied":Regex.IsMatch(ex.Message,@"(?i)WinRM|WSMan|PSSession|connect|подключ|сетевой путь|network path|разреш.*имя|resolve")?"ConnectionFailed":"Unavailable";target.Output=(ex is TimeoutException?"Передача задания не подтверждена. Оно могло успеть запуститься; состояние будет прочитано без повторного запуска.\n\n":"Не удалось передать задание на "+target.Host+". Выполнение команды не подтверждено.\n\n")+ex.Message+"\n\nУчётная запись приложения: "+Environment.UserDomainName+"\\"+Environment.UserName+"\nИспользуйте «Проверить подключение» для отдельной проверки WinRM.";Notify(target.Host+": "+ComputerRow.StatusText(target.Status)+". Подробности в результате компьютера.");}finally{deploying.Remove(job.Id+target.Host);Sync(job);if(ComputerGrid.SelectedItem is ComputerRow r&&r.JobId==job.Id&&r.Host==target.Host){ShowCurrent();}Save();if(job.Targets.All(t=>t.Status is not ("Queued" or "Sending")))Notify("Запуск: передано "+job.Targets.Count(t=>t.Status is "Submitted" or "Running")+"; недоступно "+job.Targets.Count(t=>t.Status is "ConnectionFailed" or "AccessDenied")+"; отложено "+job.Targets.Count(t=>t.Status=="InterventionRequired")+". Подробности — у каждого компьютера.");await SendQueue();}}
 static string UpdateSummary(IEnumerable<UpdateOutcome> updates)=>string.Join("\n",updates.Where(u=>!string.IsNullOrWhiteSpace(u.Title)).Select(u=>u.Title+" · "+(u.Download.HasValue?"скачивание: ":u.ResultCode.HasValue?"установка: ":"поиск: ")+((u.Download??u.ResultCode) switch{2=>"успешно",3=>"с замечаниями",4=>"ошибка",5=>"отменено",0=>"не начато",1=>"выполняется",_=>"найдено"})+(u.HResult.HasValue&&u.HResult!=0?" · HRESULT "+ExecutionDiagnosis.Code(u.HResult.Value):"")+(u.RebootRequired?" · нужна перезагрузка":"")));
 static string Timeline(string runner,IEnumerable<UpdateOutcome> updates){var rows=new List<string>();foreach(Match entry in Regex.Matches(runner,@"(?m)^([^\r\n]+?) Этап завершён: (.+); секунд: (\d+)")){string name=entry.Groups[2].Value;if(name is "WSUS · проверка и запрос отчёта" or "WSUS · установка и запрос отчёта")continue;var update=updates.FirstOrDefault(u=>name.EndsWith(u.Title)&&u.Title.Length>0);var code=name.StartsWith("Скачивание")?update?.Download:name.StartsWith("Установка")?update?.ResultCode:null;string result=code switch{2=>"успешно",3=>"с замечаниями",4=>"ошибка",5=>"отменено",_=>"завершено"};rows.Add(name+" · "+entry.Groups[3].Value+" сек · "+result);}var search=Regex.Match(runner,@"Поиск завершён\. Применимых обновлений: (\d+)");if(search.Success)rows.Add("Применимых обновлений по текущим политикам: "+search.Groups[1].Value);if(runner.Contains("Запросы завершены:"))rows.Add("Запрос отправки отчёта: команды клиента завершены; получение см. в данных сервера.");return string.Join("\n",rows);}
 static string PresentResult(string host,PollResult data){var state=data.State!;var sections=new List<string>{"## Итог задания\nКомпьютер: "+host+"\nСостояние: "+ComputerRow.StatusText(state.Status)+"\nНачало: "+LocalDateConverter.Format(state.Started)+"\nЗавершение: "+LocalDateConverter.Format(state.Ended)+(state.Error.Length>0?"\nОшибка: "+state.Error:"")};
  if(DateTimeOffset.TryParse(state.Started,out var executionStart)&&DateTimeOffset.TryParse(state.Ended,out var executionEnd)&&executionEnd>=executionStart){var duration=executionEnd-executionStart;sections[0]+="\nВыполнение на клиенте: "+(int)duration.TotalMinutes+" мин "+duration.Seconds+" сек";}
  if(state.SchemaVersion>=28&&state.HasUpdateSteps&&!state.UpdateOperationStarted&&state.Ended.Length>0)sections[0]+="\nПоиск и установка не запускались."+(state.ReportRequested?"":" Запрос отчёта не выполнялся.");
  var files=Regex.Split(data.Output,@"(?m)^--- (.+?) ---\r?$");string runner="",technical="",diagnostic="",commandOutput="";var outputFiles=data.Files??Enumerable.Range(0,(files.Length-1)/2).Select(i=>new RemoteOutputFile{Name=files[2*i+1],Body=files[2*i+2]}).ToList();foreach(var file in outputFiles){var name=file.Name;var body=file.Body.Trim();if(name.EndsWith(".err")){body=PowerShellBridge.PlainError(body);if(state.Error.Length>0&&body.StartsWith(state.Error,StringComparison.Ordinal))body="";}if(body.Length==0)continue;if(name=="runner.log")runner=body;else if(name.Contains("diagnostics."))diagnostic+="--- "+name+" ---\n"+PowerShellBridge.PlainError(body)+"\n";else if(name=="scheduler.out"){continue;}else if(name=="scheduler.err"){technical+="Внутреннее действие планировщика: "+body+"\n";}else if(name.EndsWith(".out")&&!name.Contains("report"))commandOutput+=body+"\n";else if(!name.EndsWith("updates.json"))technical+="--- "+name+" ---\n"+body+"\n";}
  if(state.RebootEvidence!=null){var reboot=state.RebootEvidence;sections.Add("## Проверка перезагрузки клиента\n"+LocalDateConverter.Format(reboot.CollectedUtc)+" · "+(reboot.Required==true?"Нужна перезагрузка. Перезагрузите в согласованное время, затем проверьте результат.":reboot.Required==false?"Флаги перезагрузки отсутствуют.":"Требование перезагрузки проверить не удалось.")+(reboot.Sources.Count>0?"\nИсточник: "+string.Join("; ",reboot.Sources.Select(ShortRebootSource)):"")+(reboot.Error.Length>0?"\nОграничения проверки: "+reboot.Error:""));}
  if(state.RebootEvidence?.Required!=true&&(state.ActivityMessage.Length>0||state.Recommendation.Length>0))sections.Add("## Контроль выполнения и рекомендации\n"+state.TransferText+"\n"+state.ActivityMessage+"\n"+state.Recommendation+(string.IsNullOrEmpty(state.Ended)&&state.RecommendationAction is "Download" or "Queue" or "Defender"?"\nДействие доступно после завершения задания. Текущее обновление продолжает выполняться.":""));if(state.Results.Count>0)sections.Add("## Результаты команд\n"+string.Join("\n",state.Results.Select(t=>t.Name+": "+(state.Status=="Cancelled"&&ReferenceEquals(t,state.Results.LastOrDefault())?"остановлено":t.ExitCode==0?(t.NativeExitCode.GetValueOrDefault()!=0?"PowerShell завершён; предупреждение: проверьте код внешней программы":"успешно"):"ошибка")+" · "+ExecutionDiagnosis.Code(t.ExitCode)+(t.NativeExitCode.HasValue?"; внешняя программа: "+ExecutionDiagnosis.Code(t.NativeExitCode.Value):""))));if(runner.Length>0)sections.Add("## Этапы выполнения\n"+Timeline(runner,data.Updates));var updates=UpdateSummary(data.Updates);if(data.Updates.Any(u=>u.Download.HasValue||u.ResultCode.HasValue))sections[0]+="\nУстановлено: "+data.Updates.Count(u=>u.ResultCode==2)+"; ошибок: "+data.Updates.Count(u=>u.Download==4||u.ResultCode==4)+"; отменено: "+data.Updates.Count(u=>u.Download==5||u.ResultCode==5);if(data.Updates.Count>0&&!data.Updates.Any(u=>u.Download.HasValue||u.ResultCode.HasValue))sections[0]+="\nПоиск завершён; найдено применимых обновлений: "+data.Updates.Count+". Установка не выполнялась.";if(updates.Length>0)sections.Add("## Результаты обновлений\n"+updates);else if(runner.Contains("Применимых обновлений: 0"))sections.Add("## Результаты обновлений\nПрименимых обновлений по текущим политикам нет.");
  if(data.Output.Contains("No Format Information")||data.Output.Contains("WARNING:"))sections.Insert(1,"## Полнота диагностики · предупреждение\nСбор завершён, но часть диагностических данных отсутствует или не расшифрована. Это ограничение диагностики, а не доказательство сбоя клиента. Исходные файлы доступны в полном журнале.");if(commandOutput.Length>0)sections.Add("## Вывод команды\n"+LogPresentation.Compact(commandOutput));var knownCodes=Regex.Matches(technical,@"(?i)(?:0x|\[)(8[0-9a-f]{7})").Cast<Match>().Select(m=>Convert.ToUInt32(m.Groups[1].Value,16)).Distinct().Take(12).ToList();if(knownCodes.Count>0)sections.Add("## Расшифровка кодов · технический контекст\nКоды из системного журнала не обязательно относятся к текущему сбою; учитывайте этап и время.\n"+string.Join("\n",knownCodes.Select(c=>"0x"+c.ToString("X8")+": "+ExecutionDiagnosis.Explain(unchecked((int)c)))));string context=LogPresentation.ErrorContext(technical);if(!context.StartsWith("В выбранном интервале"))sections.Add("## Технические подробности · ошибки и предупреждения\n"+context+"\nСовпадение по времени не доказывает причину сбоя; ошибки повторных попыток могут завершиться успехом.");if(state.DiagnosticStatus=="NotRequested"&&diagnostic.Length>0)sections.Add("## Диагностика долгой операции\n"+LogPresentation.Compact(diagnostic));if(state.DiagnosticStatus!="NotRequested")sections.Add("## Сбор диагностики\n"+DiagnosticLabel(state)+(state.DiagnosticError.Length>0?"\n"+state.DiagnosticError:"")+"\n"+diagnostic);var failureCard31=FailureCard31(data);if(failureCard31.Length>0){sections[0]=Regex.Replace(sections[0],@"(?m)^Ошибка:[^\r\n]*", "Ошибка: см. карточку причины ниже");sections.Insert(1,failureCard31);}return CompactJournal31(LogPresentation.LocalTimes(string.Join("\n\n",sections)));}
 static void Reconcile(PollResult data){var state=data.State;if(state==null)return;if((state.Status is "Queued" or "Running")&&InterruptedByBoot(state,data)){state.Status="InterventionRequired";state.Ended=DateTimeOffset.UtcNow.ToString("o");state.Error="Компьютер перезагружен после начала задания; исполнитель не работает. Результат до перезагрузки неизвестен. Автоматический повтор не запускается.";}if(state.Status is "Failed" or "CompletedWithErrors" or "Completed" or "Cancelled" or "InterventionRequired"){if(string.IsNullOrEmpty(state.StageEnded))state.StageEnded=state.Results.LastOrDefault(r=>!string.IsNullOrEmpty(r.Ended))?.Ended??state.Ended;if(string.IsNullOrEmpty(state.Ended)&&data.AgentAlive&&data.TaskState=="Running"&&state.DiagnosticStatus=="NotRequested")state.DiagnosticStatus="LegacyRunning";else if(state.DiagnosticStatus=="LegacyRunning"&&!data.AgentAlive){state.DiagnosticStatus="Failed";state.DiagnosticError="Старый исполнитель завершён. Итог сбора диагностики неизвестен.";}}if((state.DiagnosticStatus is "Pending" or "Running")&&!data.AgentAlive&&(data.TaskState is "Ready" or "Disabled" or "Missing")&&DateTimeOffset.TryParse(state.Updated,out var diagnosticUpdated)&&DateTimeOffset.UtcNow-diagnosticUpdated>TimeSpan.FromMinutes(2)){state.DiagnosticStatus="Failed";state.DiagnosticError="Исполнитель завершился без конечного результата диагностики. Основной результат сохранён.";}var failed=state.Results.LastOrDefault(r=>r.ExitCode!=0);if(failed!=null&&string.IsNullOrWhiteSpace(state.Error))state.Error="Код завершения: "+ExecutionDiagnosis.Code(failed.ExitCode)+". "+ExecutionDiagnosis.Explain(failed.ExitCode);if(state.Status=="Running"&&!string.IsNullOrWhiteSpace(state.Ended))state.Status=failed==null?"Completed":"Failed";if((state.Status is "Running" or "Queued")&&DateTimeOffset.TryParse(state.Updated,out var at)&&DateTimeOffset.UtcNow-at>TimeSpan.FromMinutes(2)&&!data.AgentAlive&&(data.TaskState is "Ready" or "Disabled" or "Missing")){state.Status="InterventionRequired";state.Error="Исполнитель больше не работает, но конечное состояние задания не сохранено. Планировщик: "+data.TaskState+", код задачи: "+(data.TaskResult.HasValue?data.TaskResult.Value+" (0x"+unchecked((uint)data.TaskResult.Value).ToString("X8")+")":"не получен")+". Код задачи не является кодом DISM/SFC. Проверьте журналы; команда автоматически не перезапускается.";}}
 static bool ShouldCollectServicing(RemoteJob? job,RemoteState? state=null)=>job!=null&&(state?.SchemaVersion>=28?state.UpdateOperationStarted||state.Results.Any(s=>System.Text.RegularExpressions.Regex.IsMatch(s.Name,@"(?i)\b(sfc|dism|chkdsk|Repair-WindowsImage)\b")):IsWsusJob(job)||job.Steps.Any(s=>Regex.IsMatch(s.Code,@"(?i)\b(sfc|dism|chkdsk|Repair-WindowsImage)\b")));
 static bool ShouldWaitReport(RemoteState state,RemoteJob? job)=>state.SchemaVersion>=28?state.ReportRequested:state.ReportRequestStatus!="Не запрошен"&&job?.Steps.Any(s=>s.Kind is "Updates" or "UpdateScan")==true;
 async Task Poll(ComputerRow row,bool force=false){
  var id=row.JobId;var host=row.Host;var key=id+host;if(id==""||!polling.Add(key))return; if(!force&&clientConnections.TryGetValue(host,out var connection)&&connection.Error.Length>0&&DateTimeOffset.UtcNow-connection.LastAttempt<TimeSpan.FromSeconds(60)){polling.Remove(key);return;}
  RefreshActivity();UpdateWsusStage();var readClock=System.Diagnostics.Stopwatch.StartNew();try{var pollTarget=History.FirstOrDefault(j=>j.Id==id)?.Targets.FirstOrDefault(t=>t.Host.Equals(host,StringComparison.OrdinalIgnoreCase))??row.Target;var data=await remote.Poll(pollTarget,id);ConnectionSucceeded(host);var sourceJob=History.FirstOrDefault(j=>j.Id==id);if(sourceJob!=null)ReconcileMissing(data,sourceJob,DateTimeOffset.UtcNow);if(data.State!=null){
   Reconcile(data);RegisterRebootPlan(sourceJob,row,data);await ObserveRebootAfterJob(row,sourceJob,data);ApplyPostBootResult(row,data);
   confirmedJobs.Add(key);var output=await Task.Run(()=>PresentResult(host,data));

   foreach(var job in History.Where(j=>j.Id==id)){var t=job.Targets.FirstOrDefault(t=>t.Host==host);if(t!=null){t.Status=data.State.Status;t.State=data.State;t.Output=output;}Sync(job);RememberSuccessful(job);}
   if(row.JobId==id){row.Target.State=data.State;row.Target.Status=data.State.Status;row.Target.Output=output;row.Refresh();if(IsCurrent(row)){ShowCurrent();}RefreshOutcomes();}Save();
   if((data.State.Status is "Completed" or "AwaitingReboot" or "RebootScheduled" or "Failed" or "CompletedWithErrors") && ShouldWaitReport(data.State,sourceJob) && wsusChecked.Add(key) && !string.IsNullOrWhiteSpace(WsusHost.Text)){reportWaiting[host]=new(){Id=id,Until=DateTimeOffset.UtcNow.AddMinutes(2),Next=DateTimeOffset.UtcNow};Store.Write("report-waits.json",reportWaiting);await FetchWsusReport(row);}
   if(data.State.Status is "Completed" or "CompletedWithErrors" or "Failed" or "Cancelled" or "VerifiedAfterReboot"){
    if(data.Client!=null&&History.Any(j=>j.Id==id&&j.Steps.Any(t=>t.Kind=="DeliveryDiagnostics"))&&wsusChecked.Add(key+"delivery")){try{var settings=ReadWsus();var evidence=await remote.DeliveryServer(settings,data.Client,data.State.Started,History.First(j=>j.Id==id).DiagnosticLookbackMinutes);var text=DeliveryPresentation.Format(data.Client,evidence,DateTimeOffset.UtcNow);deliveryReports[key]=text;Store.Write("delivery-reports.json",deliveryReports);var path=Path.Combine(Store.Root,"Diagnostics",row.Name+"_"+id+"_delivery.json");Directory.CreateDirectory(Path.GetDirectoryName(path)!);var json=JsonSerializer.Serialize(new{Client=data.Client,Server=evidence},Store.Options);File.WriteAllText(path,json);var archive=Path.Combine(Store.Root,"Logs",row.Host+"_"+id);Directory.CreateDirectory(archive);File.WriteAllText(Path.Combine(archive,"delivery-server.json"),json);if(IsCurrent(row))ShowCurrent();}catch(Exception ex){deliveryReports[key]="## Диагностика доставки отчёта\nСерверные данные не получены: "+ex.Message;if(IsCurrent(row))ShowCurrent();}}
    if(data.State.DiagnosticStatus is not ("Pending" or "Running" or "LegacyRunning")&&data.State.RestoreStatus is not ("Pending" or "InterventionRequired")&&!archivedJobs.Contains(key)){try{await remote.Logs(row.Target,id,true);archivedJobs.Add(key);Store.Write("archived-jobs.json",archivedJobs.ToList());}catch(Exception ex){if(IsCurrent(row))Notify("Результат сохранён в истории; полный архив пока получить не удалось: "+ex.Message);}}
   }
   if((data.State.Status is "Failed" or "CompletedWithErrors" or "InterventionRequired")&&ShouldCollectServicing(sourceJob,data.State)){if(wsusChecked.Add(key+"diagnostic")){try{var diagnostic=ExecutionDiagnosis.MemoryError(data.State.Error)?await remote.MemoryDiagnostics(row.Target):await remote.ServicingDiagnostics(row.Target,id,ReadDiagnosticMinutes());var folder=Path.Combine(Store.Root,"Diagnostics");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,row.Name+"_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".txt"),diagnostic,new UTF8Encoding(true));servicingReports[id+host]="## Первичная диагностика выбранного задания\n"+LogPresentation.LocalTimes(CompactDiagnostic(diagnostic));if(IsCurrent(row))ShowCurrent();}catch(Exception ex){if(IsCurrent(row))Notify("Задание остановлено; диагностику получить не удалось: "+ex.Message);}}}
  }else if(IsCurrent(row)){Notify(row.Name+": результат ещё не появился на целевом компьютере; сохранённый вывод оставлен.");}}catch(Exception ex){ConnectionFailed(host,ex.Message);if(IsCurrent(row))Notify(row.Name+": не удалось обновить результат; сохранённый вывод оставлен. "+ex.Message);}finally{polling.Remove(key);RefreshActivity();if(IsCurrent(row))UpdateWsusStage();}
 }
 async void Refresh_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{var r=ActiveRow();ShowCurrent();if(r.JobId==""){Notify("У выбранного компьютера нет задания в этом разделе. Выберите запись в истории или выполните команду.");return;}await Poll(r,true);});
 void Computer_Changed(object s,SelectionChangedEventArgs e){if(!loadingRows){if(ComputerGrid.SelectedItem is ComputerRow selected)viewState.Host=selected.Host;ShowCurrent();RevealCurrent();RefreshOutcomes();_=RefreshBackground();}}
 async void Cancel_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{var r=ActiveRow();if(r.JobId=="")throw new Exception("Нет задания для остановки.");var dialog=new StopChoice(this,r.Name,r.Target.State?.StopStatus=="ForceRequired"||(MainTabs.SelectedItem==WsusTab&&r.Target.State?.Stage.Contains("KB890830",StringComparison.OrdinalIgnoreCase)==true),MainTabs.SelectedItem==WsusTab,r.Target.State?.SupportsWuaCancel==true);if(dialog.ShowDialog()!=true)return;if(dialog.Mode=="force"&&MainTabs.SelectedItem==WsusTab){await ForceWsus(r);return;}var items=queue.ToList();var match=items.FirstOrDefault(q=>q.Job.Id==r.JobId&&q.Target.Host==r.Host);if(match.Job==null&&r.Target.Status=="Queued"&&r.Target.State==null){var saved=History.FirstOrDefault(j=>j.Id==r.JobId);var target=saved?.Targets.FirstOrDefault(t=>t.Host.Equals(r.Host,StringComparison.OrdinalIgnoreCase));if(saved!=null&&target!=null){target.Status="Cancelled";target.State=new(){Status="Cancelled",Ended=DateTime.UtcNow.ToString("o")};Sync(saved);Save();Notify("Неотправленное задание отменено.");return;}}if(match.Job!=null){queue.Clear();foreach(var q in items.Where(q=>q!=match))queue.Enqueue(q);match.Target.Status="Cancelled";match.Target.State=new(){Status="Cancelled",Ended=DateTime.UtcNow.ToString("o")};Sync(match.Job);Save();Notify("Задание удалено из очереди; команда не отправлялась.");}else{var reply=await remote.Cancel(r.Target,r.JobId,dialog.Mode);if(reply.Status=="Cancelled")CompleteLocalCancellation(r.Host,r.JobId,reply.Message);else await Poll(r,true);Notify(reply.Message);await SendQueue();}});

