 async void ServicingDiagnostics_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{var r=ActiveRow();Notify(r.Name+": сбор диагностики DISM/SFC…");string text=await remote.ServicingDiagnostics(r.Target,r.JobId,ReadDiagnosticMinutes());var folder=Path.Combine(Store.Root,"Diagnostics");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,r.Name+"_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".txt"),text,new UTF8Encoding(true));servicingReports[r.JobId+r.Host]="## Диагностика DISM / SFC выбранного задания\n"+LogPresentation.LocalTimes(LogPresentation.Compact(text));if(IsCurrent(r))ShowCurrent();Notify(r.Name+": диагностика собрана и сохранена в Data/Diagnostics.");});
 async void Diagnostics_Click(object s,RoutedEventArgs e)=>await Guard(async()=>await Submit(new(){new(){Name="WindowsUpdate.log",Kind="Diagnostics"}}));
 void OpenHistory_Click(object s,RoutedEventArgs e)=>Guard(()=>{if(SelectedHistoryJob() is not RemoteJob j)throw new Exception("Выберите задание.");FocusHistoryTarget(j,true);});
 async void Resume_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{if(SelectedHistoryJob() is not RemoteJob j)throw new Exception("Выберите задание.");if(MessageBox.Show(this,"Продолжить неотправленные цели исходного задания: "+string.Join(", ",j.Targets.Where(t=>t.Status=="Queued"&&t.State==null).Select(t=>t.Host)),"Продолжение очереди",MessageBoxButton.OKCancel)!=MessageBoxResult.OK)return;foreach(var t in j.Targets.Where(t=>t.Status=="Queued"&&t.State==null)){if(!queue.Any(q=>q.Job.Id==j.Id&&q.Target.Host==t.Host))queue.Enqueue((j,t));}await SendQueue();});
