 void ExportCsv_Click(object s,RoutedEventArgs e)=>Guard(()=>{if(SelectedHistoryJob() is not RemoteJob j)throw new Exception("Выберите задание.");var d=new SaveFileDialog{Filter="CSV|*.csv",FileName="results.csv"};if(d.ShowDialog(this)!=true)return;string Cell(string v)=>"\""+v.Replace("\"","\"\"")+"\"";File.WriteAllText(d.FileName,"Computer;Status;Updated;Error\r\n"+string.Join("\r\n",j.Targets.Select(t=>string.Join(";",new[]{Cell(t.Host),Cell(t.Status),Cell(t.State?.Updated??""),Cell(t.State?.Error??"")}))),new UTF8Encoding(true));});
 async void WsusClientRefresh_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{var row=ExecutionRow(Current(),true);if(row.JobId=="")throw new Exception("Для этого компьютера ещё нет задания.");await Poll(row);UpdateWsusStage();});
 void UpdateWsusHeader(){WsusHeader.Text=string.IsNullOrWhiteSpace(WsusHost.Text)?"WSUS не настроен · откройте настройки":"WSUS: "+WsusHost.Text+":"+WsusPort.Text+(WsusSsl.IsChecked==true?" · HTTPS":" · HTTP");}
 WsusSettings ReadWsus(){if(!int.TryParse(WsusPort.Text,out int port)||port<1||port>65535||string.IsNullOrWhiteSpace(WsusHost.Text))throw new Exception("Укажите доменное имя сервера WSUS и порт в настройках.");var host=WsusHost.Text.Trim();if(System.Net.IPAddress.TryParse(host,out _)||host.Contains('/')||host.Contains(':'))throw new Exception("Для административного WinRM-подключения укажите доменное имя сервера без http:// и порта.");return new(){Host=host,Port=port,Ssl=WsusSsl.IsChecked==true};}
 void WsusSettings_Click(object s,RoutedEventArgs e)=>MainTabs.SelectedItem=SettingsTab;
 void SaveWsus_Click(object s,RoutedEventArgs e)=>Guard(()=>{Store.Write("wsus-settings.json",ReadWsus());overviewCancel?.Cancel();overviewPaused=false;liveReports.Clear();RequestOverviewSoon();RefreshOutcomes();UpdateWsusHeader();Notify("Настройки WSUS сохранены.");});
 void RevealCurrent(){if(ComputerGrid.SelectedItem is ComputerRow r&&computerNodes.TryGetValue(r.Host,out var leaf)){for(var parent=ItemsControl.ItemsControlFromItemContainer(leaf) as TreeViewItem;parent!=null;parent=ItemsControl.ItemsControlFromItemContainer(parent) as TreeViewItem)parent.IsExpanded=true;leaf.IsSelected=true;leaf.BringIntoView();}}
 static string DiagnosticLabel(RemoteState state){var label=state.DiagnosticStatus switch{"Pending"=>"ожидает сбора","Running"=>"собирается · лимит 5 минут","LegacyRunning"=>"старый исполнитель ещё работает; ограничение новой версии к нему не применяется","Completed"=>"собрана","TimedOut"=>"остановлена по лимиту/запросу; доступны частичные журналы","Failed"=>"не завершена",_=>"не запрошена"};if(state.DiagnosticStatus=="Running"&&DateTimeOffset.TryParse(state.DiagnosticStarted,out var start))label+=" · "+(int)(DateTimeOffset.UtcNow-start).TotalSeconds+" сек";return label+(state.DiagnosticError==""?"":" · "+state.DiagnosticError);}

 int ReadDiagnosticMinutes(){if(!int.TryParse(DiagnosticMinutes.Text,out var minutes)||minutes<0||minutes>1440)throw new Exception("Интервал диагностики: от 0 до 1440 минут перед заданием.");return minutes;}
 void SaveDiagnosticSettings_Click(object s,RoutedEventArgs e)=>Guard(()=>{Store.Write("diagnostic-settings.json",ReadDiagnosticMinutes());Notify("Интервал диагностики сохранён.");});
 void PaintReport(string host){WsusServerOutput.Background=System.Windows.Media.Brushes.White;WsusReportTitle.Text="Данные сервера WSUS о выбранном ПК"+(reportCache.ContainsKey(host)&&!liveReports.Contains(host)?" · сохранённый снимок":"");WsusReportTitle.ToolTip="Главный счётчик учитывает одобрение именно для клиента и известную серверу применимость. Полная статистика всех обновлений раскрывается отдельно.";}

 void RefreshOutcomes(){foreach(var entry in reportCache.Where(x=>CacheMatches(x.Value))){var value=entry.Value.Found?entry.Value.Report.Severity(""):"Unknown";reportSeverity[entry.Key]=value=="Success"&&!liveReports.Contains(entry.Key)?"Stale":value;}foreach(var row in Computers){var status=OverviewStatus(row);row.SetOutcome(status.Kind,status.Hint);row.SetConnection(LinkKind(row.Host),LinkHint(row));}RefreshActivity();RefreshStatusCounts();RefreshRebootHeader();}

 async Task FetchWsusReport(ComputerRow row){if(!reportReading.Add(row.Host))return;try{await ReadClientStatus(row);var settings=ReadWsus();var result=await remote.Wsus(settings.Host,settings.Port,settings.Ssl,ConnectionStore.WsusName(row.Host));var report=JsonSerializer.Deserialize<WsusReport>(result,Store.Options)??throw new Exception("Пустой отчёт WSUS.");var started=reportWaiting.TryGetValue(row.Host,out var pending)?History.FirstOrDefault(j=>j.Id==pending.Id)?.Targets.FirstOrDefault(t=>t.Host.Equals(row.Host,StringComparison.OrdinalIgnoreCase))?.State?.Started??"":ExecutionRow(row,true).Target.State?.Started??"";var context=ExecutionRow(row,true).Target.State;if(context?.SchemaVersion>=28&&!context.UpdateOperationStarted&&!context.ReportRequested)started="";overviewErrors.Remove(row.Host);SaveReportCache(row.Host,report,settings.Host+":"+settings.Port,started);serverReports[row.Host]=report.Format(settings.Host+":"+settings.Port,started);reportSeverity[row.Host]=report.Severity(started);if(report.Fresh(started))reportWaiting.Remove(row.Host);if(IsCurrent(row)){WsusServerOutput.Text=serverReports[row.Host];PaintReport(row.Host);Notify(row.Name+": данные сервера WSUS прочитаны.");}RefreshOutcomes();await CheckOldReport(row,report);await ExplainServerFailures(row,report);}catch(Exception ex){serverReports[row.Host]="Не удалось прочитать данные сервера WSUS: "+ex.Message;overviewErrors[row.Host]=ex.Message;if(IsCurrent(row)){WsusServerOutput.Text=serverReports[row.Host];PaintReport(row.Host);}RefreshOutcomes();}finally{reportReading.Remove(row.Host);Store.Write("report-waits.json",reportWaiting);}}

 async Task ConfirmPendingReports(){foreach(var entry in reportWaiting.ToList()){if(DateTimeOffset.UtcNow<entry.Value.Next)continue;if(DateTimeOffset.UtcNow>=entry.Value.Until){reportWaiting.Remove(entry.Key);if(serverReports.ContainsKey(entry.Key)){serverReports[entry.Key]+="\nОжидание свежего отчёта завершено (2 минуты). Это не новая ошибка клиента. Данные сервера можно прочитать позже.";if((ComputerGrid.SelectedItem as ComputerRow)?.Host.Equals(entry.Key,StringComparison.OrdinalIgnoreCase)==true)WsusServerOutput.Text=serverReports[entry.Key];}continue;}entry.Value.Next=DateTimeOffset.UtcNow.AddSeconds(15);var row=Computers.FirstOrDefault(r=>r.Host.Equals(entry.Key,StringComparison.OrdinalIgnoreCase))??History.Where(j=>j.Id==entry.Value.Id).SelectMany(j=>j.Targets).Where(t=>t.Host.Equals(entry.Key,StringComparison.OrdinalIgnoreCase)).Select(t=>new ComputerRow(t,entry.Value.Id)).FirstOrDefault();if(row!=null)await FetchWsusReport(row);}Store.Write("report-waits.json",reportWaiting);}
 async void Wsus_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{ReadWsus();var marked=Selected();var dialog=new TargetConfirmation(this,ComputerGrid.SelectedItem as ComputerRow,marked,"Чтение данных клиентов с сервера WSUS; команды на клиентах не запускаются.");if(dialog.ShowDialog()!=true)return;foreach(var row in dialog.Result!)await FetchWsusReport(row);ShowCurrent();});
 async Task WsusJob(string kind){ReadWsus();MicrosoftBox.IsChecked=false;if(kind=="UpdateScan")RebootBox.IsChecked=false;await Submit(new(){new(){Name=kind=="UpdateScan"?"WSUS · проверка и запрос отчёта":"WSUS · установка и запрос отчёта",Kind=kind}},"WSUS");MainTabs.SelectedItem=WsusTab;ShowCurrent();}
 async void WsusScan_Click(object s,RoutedEventArgs e)=>await Guard(async()=>await WsusJob("UpdateScan"));
 async void WsusInstall_Click(object s,RoutedEventArgs e)=>await Guard(async()=>await WsusJob("Updates"));
 void AutoScroll_Changed(object s,RoutedEventArgs e){if(OutputBox==null||WsusOutput==null||AutoScrollSetting==null)return;var enabled=AutoScrollSetting.IsChecked==true;OutputBox.AutoScroll=enabled;WsusOutput.AutoScroll=enabled;if(IsLoaded)Store.Write("journal-autoscroll.json",enabled);}
 void DiagnosticGroup_Changed(object s,RoutedEventArgs e){if(IsLoaded&&WsusDiagnosticsGroup!=null)Store.Write("wsus-diagnostics-expanded.json",WsusDiagnosticsGroup.IsExpanded);}
 async void RecoverReport_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{ReadWsus();MicrosoftBox.IsChecked=false;RebootBox.IsChecked=false;var keep=false;var code="$keepBackup="+(keep?"$true":"$false")+";"+DeliveryScripts.Recovery;await Submit(new(){new(){Name="Очистка очереди: неотправленные события исключаются из отправки",Kind="ReportRecovery",Code=code},new(){Name="WSUS · проверка и запрос свежего отчёта",Kind="UpdateScan"}},"WSUS");});
 async void DeliveryDiagnostics_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{ReadWsus();MicrosoftBox.IsChecked=false;RebootBox.IsChecked=false;await Submit(new(){new(){Name="Сбор данных клиента и запрос отчёта WSUS",Kind="DeliveryDiagnostics",Code=DeliveryScripts.Client},new(){Name="Сбор журнала отчётности Windows Update",Kind="Diagnostics"}},"WSUS");});
 async void WsusDiagnostics_Click(object s,RoutedEventArgs e)=>await Guard(async()=>{MicrosoftBox.IsChecked=false;await Submit(new(){new(){Name="Сбор диагностических данных WSUS клиента",Kind="ClientDiagnostics",Code=DeliveryScripts.Client.Replace("После этого будет запрошена только отправка отчёта, поиск и установка не запускаются.","Поиск, установка и отправка отчёта не запускаются.")},new(){Name="Сбор WindowsUpdate.log",Kind="Diagnostics"}},"WSUS");MainTabs.SelectedItem=WsusTab;});

 static bool FindExpanded(ItemsControl parent,string dn){foreach(TreeViewItem item in parent.Items){if(item.Tag is OuBranchState branch&&branch.DN==dn)return item.IsExpanded;if(FindExpanded(item,dn))return true;}return false;}
 void OnClosing(object? s,CancelEventArgs e){if(queue.Count>0||History.SelectMany(j=>j.Targets).Any(t=>t.Status=="Sending")){if(MessageBox.Show(this,"Переданные задания продолжат работу. Закрыть командный пункт?","Закрытие",MessageBoxButton.YesNo)!=MessageBoxResult.Yes){e.Cancel=true;return;}}Store.Write("status-filter.json",statusFilter.ToList());Store.Write("status-scope.json",statusScope);closing=true;overviewCancel?.Cancel();timer.Stop();rebootTimer.Stop();viewState.Host=(ComputerGrid.SelectedItem as ComputerRow)?.Host??viewState.Host;viewState.Tab=MainTabs.SelectedIndex;viewState.Search=SearchBox.Text;viewState.Expanded=branches.Keys.Where(k=>FindExpanded(OuTree,k)).ToList();Store.Write("view-state.json",viewState);SaveCommandLayout();Save();}
}

public sealed class CommandLayout {public double EditorRatio {get;set;}=0.24;}
public sealed class CommandSuggestion {public LibraryEntry Entry {get;set;}=new();public string Source {get;set;}="";public string Name=>Entry.Name;public string Detail=>Source+" · "+string.Join(" / ",Entry.Steps.Select(t=>t.Kind).Distinct())+(Entry.Steps.Count>1?" · шагов: "+Entry.Steps.Count:"");public string Preview=>string.Join("\n\n",Entry.Steps.Select(t=>t.Code));}

public sealed class ViewState {public bool RecentExpanded {get;set;}=true;public bool TreeExpanded {get;set;}=true;public double RecentRatio {get;set;}=0.38;public string Host {get;set;}="";public string Search {get;set;}="";public int Tab {get;set;}public List<string> Expanded {get;set;}=new();}



